import{_ as s,c as a,o as n,j as i,Y as r,t as o}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"math_error | x-cmd man (man7) | detecting errors from mathematical functions","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | math_error - detecting errors from mathematical functions","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"math_error | x-cmd man (man7) | detecting errors from mathematical functions"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | math_error - detecting errors from mathematical functions"}]]},"headers":[],"params":{"isMan":true,"man":"math_error","category":"man7","desc":"detecting errors from mathematical functions"},"relativePath":"man7/math_error.md","filePath":"man7/[man].md"}'),h={name:"man7/math_error.md"},l={class:"visually-hidden"};function p(t,e,c,d,m,g){return n(),a("div",null,[i("h1",l,o(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>math_error - detecting errors from mathematical functions</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#include &lt;math.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#include &lt;errno.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#include &lt;fenv.h&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>When an error occurs, most library functions indicate this fact by returning a special value (e.g., -1 or NULL). Because they typically return a floating-point number, the mathematical functions declared in <em>&lt;math.h&gt;</em> indicate an error using other mechanisms. There are two error-reporting mechanisms: the older one sets <em>errno</em>; the newer one uses the floating-point exception mechanism (the use of <strong>feclearexcept</strong>(3) and <strong>fetestexcept</strong>(3), as outlined below) described in <strong>fenv</strong>(3).</p><p>A portable program that needs to check for an error from a mathematical function should set <em>errno</em> to zero, and make the following call</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feclearexcept(FE_ALL_EXCEPT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>before calling a mathematical function.</p><p>Upon return from the mathematical function, if <em>errno</em> is nonzero, or the following call (see <strong>fenv</strong>(3)) returns nonzero</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetestexcept(FE_INVALID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FE_DIVBYZERO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FE_OVERFLOW</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FE_UNDERFLOW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>then an error occurred in the mathematical function.</p><p>The error conditions that can occur for mathematical functions are described below.</p><h3 id="domain-error" tabindex="-1">Domain error <a class="header-anchor" href="#domain-error" aria-label="Permalink to &quot;Domain error&quot;">​</a></h3><p>A <em>domain error</em> occurs when a mathematical function is supplied with an argument whose value falls outside the domain for which the function is defined (e.g., giving a negative argument to <strong>log</strong>(3)). When a domain error occurs, math functions commonly return a NaN (though some functions return a different value in this case); <em>errno</em> is set to <strong>EDOM</strong>, and an &quot;invalid&quot; (<strong>FE_INVALID</strong>) floating-point exception is raised.</p><h3 id="pole-error" tabindex="-1">Pole error <a class="header-anchor" href="#pole-error" aria-label="Permalink to &quot;Pole error&quot;">​</a></h3><p>A <em>pole error</em> occurs when the mathematical result of a function is an exact infinity (e.g., the logarithm of 0 is negative infinity). When a pole error occurs, the function returns the (signed) value <strong>HUGE_VAL</strong>, <strong>HUGE_VALF</strong>, or <strong>HUGE_VALL</strong>, depending on whether the function result type is <em>double</em>, <em>float</em>, or <em>long double</em>. The sign of the result is that which is mathematically correct for the function. <em>errno</em> is set to <strong>ERANGE</strong>, and a &quot;divide-by-zero&quot; (<strong>FE_DIVBYZERO</strong>) floating-point exception is raised.</p><h3 id="range-error" tabindex="-1">Range error <a class="header-anchor" href="#range-error" aria-label="Permalink to &quot;Range error&quot;">​</a></h3><p>A <em>range error</em> occurs when the magnitude of the function result means that it cannot be represented in the result type of the function. The return value of the function depends on whether the range error was an overflow or an underflow.</p><p>A floating result <em>overflows</em> if the result is finite, but is too large to represented in the result type. When an overflow occurs, the function returns the value <strong>HUGE_VAL</strong>, <strong>HUGE_VALF</strong>, or <strong>HUGE_VALL</strong>, depending on whether the function result type is <em>double</em>, <em>float</em>, or <em>long double</em>. <em>errno</em> is set to <strong>ERANGE</strong>, and an &quot;overflow&quot; (<strong>FE_OVERFLOW</strong>) floating-point exception is raised.</p><p>A floating result <em>underflows</em> if the result is too small to be represented in the result type. If an underflow occurs, a mathematical function typically returns 0.0 (C99 says a function shall return &quot;an implementation-defined value whose magnitude is no greater than the smallest normalized positive number in the specified type&quot;). <em>errno</em> may be set to <strong>ERANGE</strong>, and an &quot;underflow&quot; (<strong>FE_UNDERFLOW</strong>) floating-point exception may be raised.</p><p>Some functions deliver a range error if the supplied argument value, or the correct function result, would be <em>subnormal</em>. A subnormal value is one that is nonzero, but with a magnitude that is so small that it can&#39;t be presented in normalized form (i.e., with a 1 in the most significant bit of the significand). The representation of a subnormal number will contain one or more leading zeros in the significand.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The <em>math_errhandling</em> identifier specified by C99 and POSIX.1 is not supported by glibc. This identifier is supposed to indicate which of the two error-notification mechanisms (<em>errno</em>, exceptions retrievable via <strong>fetestexcept</strong>(3)) is in use. The standards require that at least one be in use, but permit both to be available. The current (glibc 2.8) situation under glibc is messy. Most (but not all) functions raise exceptions on errors. Some also set <em>errno</em>. A few functions set <em>errno</em>, but don&#39;t raise an exception. A very few functions do neither. See the individual manual pages for details.</p><p>To avoid the complexities of using <em>errno</em> and <strong>fetestexcept</strong>(3) for error checking, it is often advised that one should instead check for bad argument values before each call. For example, the following code ensures that <strong>log</strong>(3)&#39;s argument is not a NaN and is not zero (a pole error) or less than zero (a domain error):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">double</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isnan(x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> islessequal(x,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Deal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NaN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> domain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The discussion on this page does not apply to the complex mathematical functions (i.e., those declared by <em>&lt;complex.h&gt;</em>), which in general are not required to return errors by C99 and POSIX.1.</p><p>The <strong>gcc</strong>(1) <em>-fno-math-errno</em> option causes the executable to employ implementations of some mathematical functions that are faster than the standard implementations, but do not set <em>errno</em> on error. (The <strong>gcc</strong>(1) <em>-ffast-math</em> option also enables <em>-fno-math-errno</em>.) An error can still be tested for using <strong>fetestexcept</strong>(3).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gcc</strong>(1), <strong>errno</strong>(3), <strong>fenv</strong>(3), <strong>fpclassify</strong>(3), <strong>INFINITY</strong>(3), <strong>isgreater</strong>(3), <strong>matherr</strong>(3), <strong>nan</strong>(3)</p><p><em>info libc</em></p>`,31))])}const f=s(h,[["render",p]]);export{k as __pageData,f as default};
